ui.css:
.hud-panel{position:relative;padding:7px 14px 7px 8px;background:rgba(6,42,74,.84);border:1.5px solid #dff3ff;font:400 15px 'Share Tech Mono',monospace;color:#f2faff}
.hud-panel::before{content:'FIG. 1';position:absolute;top:-9px;left:8px;padding:0 5px;font:400 10px/16px 'Share Tech Mono',monospace;letter-spacing:2px;color:#a9dcf6;background:#0b4475;border:1px solid rgba(223,243,255,.55)}
.bar{position:relative;width:230px;height:16px;border:1.5px solid #dff3ff;background:rgba(3,26,48,.85)}
.bar::after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 22px,rgba(223,243,255,.5) 22px 23px)}
.bar-fill{height:100%;background:repeating-linear-gradient(45deg,rgba(236,248,255,.95) 0 1.6px,transparent 1.6px 4.6px),rgba(236,248,255,.14);border-right:2px solid #f2faff}
.ruler{height:16px;border:1.5px solid #dff3ff;background:repeating-linear-gradient(90deg,rgba(223,243,255,.6) 0 1px,transparent 1px 10px) left bottom/100% 5px no-repeat,rgba(6,42,74,.84)}
.ruler-fill{height:100%;background:repeating-linear-gradient(-45deg,rgba(255,207,74,.95) 0 1.5px,transparent 1.5px 5px),rgba(255,207,74,.16);border-right:2px solid #ffcf4a}
.stamp{display:inline-block;padding:3px 16px;color:#ff6b5c;font:400 26px 'Share Tech Mono',monospace;letter-spacing:2px;border:2.5px solid #ff6b5c;border-radius:5px;outline:1px solid rgba(255,107,92,.55);outline-offset:3px;transform:rotate(-2.5deg)}
.card{position:relative;width:236px;min-height:312px;padding:26px 18px 52px;color:#f2faff;background:linear-gradient(rgba(200,235,255,.06) 1px,transparent 1px) 0 0/12px 12px,linear-gradient(90deg,rgba(200,235,255,.06) 1px,transparent 1px) 0 0/12px 12px,#0d4f86;border:1.5px solid #dff3ff;box-shadow:inset 0 0 0 6px #0d4f86,inset 0 0 0 7px rgba(223,243,255,.5)}
.card::after{content:'DWG A-01   SCALE 1:1';position:absolute;left:7px;right:7px;bottom:7px;height:26px;border-top:1px solid rgba(223,243,255,.55);font:400 10px/26px 'Share Tech Mono',monospace;letter-spacing:2px;color:#a9dcf6;text-align:center}
